INSERT INTO "program" ("id", "slug", "title", "description", "tag", "category", "sort_order", "published") VALUES
  ('p_intro-latin-1', 'intro-latin-1', '{"en": "Intro to Latin 1.0"}'::jsonb, '{"en": "Three dances. Your first introduction to Latin.", "uk": "Три танці. Твоя перша зустріч із латиною."}'::jsonb, '{"en": "START HERE", "uk": "ПОЧНИ ТУТ"}'::jsonb, '{"en": "Intro", "uk": "Intro"}'::jsonb, 0, true),
  ('p_intro-latin-2', 'intro-latin-2', '{"en": "Intro to Latin 2.0"}'::jsonb, '{"en": "More technique, musicality and freedom.", "uk": "Більше техніки, музикальності та свободи."}'::jsonb, '{"en": "THE NEXT STEP", "uk": "НАСТУПНИЙ КРОК"}'::jsonb, '{"en": "Intro", "uk": "Intro"}'::jsonb, 1, true),
  ('p_beginner-1', 'beginner-1', '{"en": "Beginner 1.0"}'::jsonb, '{"en": "Five dances. The full spectrum of Latin.", "uk": "П’ять танців. Повна палітра латини."}'::jsonb, '{"en": "FOUNDATION", "uk": "БАЗОВИЙ РІВЕНЬ"}'::jsonb, '{"en": "Beginner", "uk": "Beginner"}'::jsonb, 2, true),
  ('p_beginner-2', 'beginner-2', '{"en": "Beginner 2.0"}'::jsonb, '{"en": "Build a solid foundation and connect your moves.", "uk": "Побудуй сильну основу та поєднуй рухи."}'::jsonb, '{"en": "GROWTH", "uk": "РОЗВИТОК"}'::jsonb, '{"en": "Beginner", "uk": "Beginner"}'::jsonb, 3, true),
  ('p_beginner-3', 'beginner-3', '{"en": "Beginner 3.0"}'::jsonb, '{"en": "From individual steps to expressive combinations.", "uk": "Від окремих кроків до виразних комбінацій."}'::jsonb, '{"en": "PRACTICE", "uk": "ПРАКТИКА"}'::jsonb, '{"en": "Beginner", "uk": "Beginner"}'::jsonb, 4, true),
  ('p_beginner-4', 'beginner-4', '{"en": "Beginner 4.0"}'::jsonb, '{"en": "Dance with flow. Add character and confidence.", "uk": "Танцюй цілісно. Додай характер і впевненість."}'::jsonb, '{"en": "CONFIDENCE", "uk": "ВПЕВНЕНІСТЬ"}'::jsonb, '{"en": "Beginner", "uk": "Beginner"}'::jsonb, 5, true),
  ('p_salsa-essentials', 'salsa-essentials', '{"en": "Salsa essentials"}'::jsonb, '{"en": "Feel the pulse of salsa and master the basics.", "uk": "Відчуй пульс сальси та опануй базові кроки."}'::jsonb, '{"en": "SOCIAL DANCE", "uk": "СОЦІАЛЬНІ ТАНЦІ"}'::jsonb, '{"en": "Salsa", "uk": "Salsa"}'::jsonb, 6, true);
