INSERT INTO "lesson" ("id", "course_id", "title", "description", "duration_minutes", "sort_order") VALUES
  ('l_intro-latin-1_cha-cha-cha_1', 'c_intro-latin-1_cha-cha-cha', '{"en": "Finding the rhythm", "uk": "Знайомство з ритмом"}'::jsonb, '{"en": "Explore the character of the dance, musical counts and weight transfer. Start slowly: confidence grows from mindful movement.", "uk": "Розберемо характер танцю, музичний рахунок і перенесення ваги. Почни повільно: впевненість народжується з усвідомленого руху."}'::jsonb, 18, 0),
  ('l_intro-latin-1_cha-cha-cha_2', 'c_intro-latin-1_cha-cha-cha', '{"en": "Basic step technique", "uk": "Техніка базового кроку"}'::jsonb, '{"en": "Work on posture, balance and precise footwork. Repeat each element a few times at a comfortable pace.", "uk": "Працюємо над положенням корпусу, опорою та точністю кроку. Повтори кожен елемент кілька разів у комфортному темпі."}'::jsonb, 24, 1),
  ('l_intro-latin-1_cha-cha-cha_3', 'c_intro-latin-1_cha-cha-cha', '{"en": "Your first combination", "uk": "Твоя перша комбінація"}'::jsonb, '{"en": "Connect the basic elements into a short sequence. Focus on transitions and staying in rhythm.", "uk": "Поєднаємо базові елементи в коротку послідовність. Зверни увагу на переходи й збереження ритму."}'::jsonb, 22, 2),
  ('l_intro-latin-1_cha-cha-cha_4', 'c_intro-latin-1_cha-cha-cha', '{"en": "Practice with music", "uk": "Практика під музику"}'::jsonb, '{"en": "Bring it all together: movement, rhythm and your own character. Practice without music first, then add tempo.", "uk": "Збери все разом: рух, ритм та власний характер. Спочатку потренуйся без музики, потім додай темп."}'::jsonb, 20, 3),
  ('l_intro-latin-1_samba_1', 'c_intro-latin-1_samba', '{"en": "Finding the rhythm", "uk": "Знайомство з ритмом"}'::jsonb, '{"en": "Explore the character of the dance, musical counts and weight transfer. Start slowly: confidence grows from mindful movement.", "uk": "Розберемо характер танцю, музичний рахунок і перенесення ваги. Почни повільно: впевненість народжується з усвідомленого руху."}'::jsonb, 18, 0),
